// =============================================================
// Node: Check LinkedIn Token Expiry
// Refreshes tokens expiring within the next 14 days
// LinkedIn tokens cannot be silently refreshed — flag them only
// (LinkedIn requires user re-auth to get a new token)
// =============================================================

const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

const now       = new Date();
const threshold = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000); // 14 days ahead

// Fetch all active LinkedIn tokens
const res = await this.helpers.httpRequest({
  method: 'GET',
  url: supabaseUrl + '/rest/v1/linkedin_tokens',
  headers: {
    'apikey':        serviceKey,
    'Authorization': 'Bearer ' + serviceKey
  },
  qs: { is_active: 'eq.true', select: 'member_email,linkedin_name,token_expires_at' }
});

const tokens = Array.isArray(res) ? res : [];

const expiringSoon = tokens.filter(t => {
  if (!t.token_expires_at) return false;
  const exp = new Date(t.token_expires_at);
  return exp <= threshold;
});

const alreadyExpired = expiringSoon.filter(t => new Date(t.token_expires_at) <= now);
const expiringSoonOnly = expiringSoon.filter(t => new Date(t.token_expires_at) > now);

console.log(`LinkedIn token check: ${tokens.length} total, ${expiringSoon.length} expiring within 14 days`);

return [{
  json: {
    platform: 'linkedin',
    checked_at: now.toISOString(),
    total_tokens: tokens.length,
    expiring_soon: expiringSoonOnly.map(t => ({ email: t.member_email, name: t.linkedin_name, expires_at: t.token_expires_at })),
    already_expired: alreadyExpired.map(t => ({ email: t.member_email, name: t.linkedin_name, expires_at: t.token_expires_at }))
  }
}];

// =============================================================
// Node: Check & Refresh Facebook Token Expiry
// Facebook long-lived tokens (60 days) can be refreshed by
// calling the token endpoint with the existing valid token.
// Refreshes tokens expiring within 14 days automatically.
// =============================================================

const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;
const appId       = $env.FACEBOOK_APP_ID;
const appSecret   = $env.FACEBOOK_APP_SECRET;

const now       = new Date();
const threshold = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000);

// Fetch active Facebook tokens expiring within 14 days
const res = await this.helpers.httpRequest({
  method: 'GET',
  url: supabaseUrl + '/rest/v1/facebook_tokens',
  headers: {
    'apikey':        serviceKey,
    'Authorization': 'Bearer ' + serviceKey
  },
  qs: { is_active: 'eq.true', select: 'id,member_email,facebook_name,access_token,token_expires_at' }
});

const tokens = Array.isArray(res) ? res : [];

const toRefresh = tokens.filter(t => {
  if (!t.token_expires_at) return false;
  const exp = new Date(t.token_expires_at);
  return exp <= threshold;
});

console.log(`Facebook token check: ${tokens.length} total, ${toRefresh.length} need refresh`);

const results = [];

for (const token of toRefresh) {
  try {
    // Refresh long-lived token
    const refreshRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/oauth/access_token',
      qs: {
        grant_type:        'fb_exchange_token',
        client_id:         appId,
        client_secret:     appSecret,
        fb_exchange_token: token.access_token
      }
    });

    if (!refreshRes.access_token) {
      throw new Error('Refresh response missing access_token');
    }

    const expiresIn  = refreshRes.expires_in || 5184000; // 60 days default
    const storedAt   = now.toISOString();
    const expiresAt  = new Date(now.getTime() + expiresIn * 1000).toISOString();

    // Update Supabase record
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: supabaseUrl + '/rest/v1/facebook_tokens?member_email=eq.' + encodeURIComponent(token.member_email),
      headers: {
        'apikey':        serviceKey,
        'Authorization': 'Bearer ' + serviceKey,
        'Content-Type':  'application/json'
      },
      body: JSON.stringify({
        access_token:     refreshRes.access_token,
        expires_in:       expiresIn,
        token_stored_at:  storedAt,
        token_expires_at: expiresAt,
        updated_at:       now.toISOString()
      })
    });

    results.push({ email: token.member_email, name: token.facebook_name, status: 'refreshed', new_expires_at: expiresAt });
    console.log('Facebook token refreshed for ' + token.member_email);

  } catch (err) {
    results.push({ email: token.member_email, name: token.facebook_name, status: 'error', error: err.message });
    console.error('Facebook token refresh failed for ' + token.member_email + ': ' + err.message);
  }
}

return [{
  json: {
    platform: 'facebook',
    checked_at: now.toISOString(),
    total_tokens: tokens.length,
    refresh_results: results
  }
}];

// =============================================================
// Node: Check & Refresh Instagram Token Expiry
// Instagram long-lived tokens (60 days) can be refreshed
// using the refresh_access_token endpoint.
// Refreshes tokens expiring within 14 days automatically.
// =============================================================

const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

const now       = new Date();
const threshold = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000);

// Fetch active Instagram tokens
const res = await this.helpers.httpRequest({
  method: 'GET',
  url: supabaseUrl + '/rest/v1/instagram_tokens',
  headers: {
    'apikey':        serviceKey,
    'Authorization': 'Bearer ' + serviceKey
  },
  qs: { is_active: 'eq.true', select: 'id,member_email,instagram_name,access_token,token_expires_at' }
});

const tokens = Array.isArray(res) ? res : [];

const toRefresh = tokens.filter(t => {
  if (!t.token_expires_at) return false;
  const exp = new Date(t.token_expires_at);
  return exp <= threshold;
});

console.log(`Instagram token check: ${tokens.length} total, ${toRefresh.length} need refresh`);

const results = [];

for (const token of toRefresh) {
  try {
    // Refresh long-lived Instagram token
    const refreshRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.instagram.com/refresh_access_token',
      qs: {
        grant_type:   'ig_refresh_token',
        access_token: token.access_token
      }
    });

    if (!refreshRes.access_token) {
      throw new Error('Refresh response missing access_token');
    }

    const expiresIn  = refreshRes.expires_in || 5184000;
    const storedAt   = now.toISOString();
    const expiresAt  = new Date(now.getTime() + expiresIn * 1000).toISOString();

    await this.helpers.httpRequest({
      method: 'PATCH',
      url: supabaseUrl + '/rest/v1/instagram_tokens?member_email=eq.' + encodeURIComponent(token.member_email),
      headers: {
        'apikey':        serviceKey,
        'Authorization': 'Bearer ' + serviceKey,
        'Content-Type':  'application/json'
      },
      body: JSON.stringify({
        access_token:     refreshRes.access_token,
        expires_in:       expiresIn,
        token_stored_at:  storedAt,
        token_expires_at: expiresAt,
        updated_at:       now.toISOString()
      })
    });

    results.push({ email: token.member_email, name: token.instagram_name, status: 'refreshed', new_expires_at: expiresAt });
    console.log('Instagram token refreshed for ' + token.member_email);

  } catch (err) {
    results.push({ email: token.member_email, name: token.instagram_name, status: 'error', error: err.message });
    console.error('Instagram token refresh failed for ' + token.member_email + ': ' + err.message);
  }
}

return [{
  json: {
    platform: 'instagram',
    checked_at: now.toISOString(),
    total_tokens: tokens.length,
    refresh_results: results
  }
}];

// =============================================================
// Node: Compile Report & Alert on LinkedIn Expiry
// Sends a summary email if any LinkedIn tokens need re-auth,
// or if Facebook/Instagram refresh failures occurred.
// Uses Gmail via n8n's HTTP Request to a send-email webhook
// or log to console for now.
// =============================================================

const allItems = $input.all();
const linkedinReport  = allItems.find(i => i.json.platform === 'linkedin')?.json  || {};
const facebookReport  = allItems.find(i => i.json.platform === 'facebook')?.json  || {};
const instagramReport = allItems.find(i => i.json.platform === 'instagram')?.json || {};

const issues = [];

// LinkedIn — cannot auto-refresh, flag for manual re-auth
if (linkedinReport.already_expired?.length) {
  issues.push('EXPIRED LinkedIn tokens: ' + linkedinReport.already_expired.map(t => t.email).join(', '));
}
if (linkedinReport.expiring_soon?.length) {
  issues.push('EXPIRING SOON LinkedIn tokens: ' + linkedinReport.expiring_soon.map(t => t.email + ' (expires ' + t.expires_at + ')').join(', '));
}

// Facebook refresh failures
const fbFailed = (facebookReport.refresh_results || []).filter(r => r.status === 'error');
if (fbFailed.length) {
  issues.push('Facebook refresh FAILED: ' + fbFailed.map(r => r.email + ' — ' + r.error).join('; '));
}

// Instagram refresh failures
const igFailed = (instagramReport.refresh_results || []).filter(r => r.status === 'error');
if (igFailed.length) {
  issues.push('Instagram refresh FAILED: ' + igFailed.map(r => r.email + ' — ' + r.error).join('; '));
}

const summary = {
  run_at: new Date().toISOString(),
  linkedin: {
    total: linkedinReport.total_tokens || 0,
    expiring_soon_count: (linkedinReport.expiring_soon || []).length,
    expired_count: (linkedinReport.already_expired || []).length
  },
  facebook: {
    total: facebookReport.total_tokens || 0,
    refreshed: (facebookReport.refresh_results || []).filter(r => r.status === 'refreshed').length,
    failed: fbFailed.length
  },
  instagram: {
    total: instagramReport.total_tokens || 0,
    refreshed: (instagramReport.refresh_results || []).filter(r => r.status === 'refreshed').length,
    failed: igFailed.length
  },
  issues_found: issues.length > 0,
  issues
};

console.log('Token Refresh Report:', JSON.stringify(summary, null, 2));

if (issues.length > 0) {
  console.warn('ACTION REQUIRED — token issues detected:\n' + issues.join('\n'));
  // TODO: wire up Gmail node or Slack notification here
  // For now, the summary is logged and visible in n8n execution history
}

return [{ json: summary }];
